let raw = $input.first().json.text;
raw = raw.replace(/```json/g,'').replace(/```/g,'').trim();

let topics = [];
try {
  topics = JSON.parse(raw);
} catch(e) {
  topics = [];
}
// Smeni go svoj apiKey
return topics.map(topic => ({
  json: {
    query: topic,
    url: `https://serpapi.com/search.json?q=${encodeURIComponent(topic + ' youtube')}&tbm=vid&api_key=df34ac473a41aba1af5868124849522f1e5ff9c9a0fcf95722a33909867f19c4`
  }
}));

// @ts-nocheck
const results = $input.all();

const links = results
  .map(item => {
    const videos = item.json.video_results || [];
    const firstVideo = videos.find(v => 
      v.link && v.link.includes('youtube.com/watch')
    );
    return {
      section: item.json.search_parameters?.q?.replace(' youtube','').trim() || 'Topic',
      url: firstVideo ? firstVideo.link : null
    };
  })
  .filter(item => item.url !== null);

return [{ json: { youtubeLinks: links } }];

